        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = (window.mySimulation && window.mySimulation.state)
                ? window.mySimulation.state.domainState : {};
            var totalWelfare = ds.cumulativeWelfare || 0;
            var funded = ds.projectsFunded || 0;
            var attempted = ds.projectsAttempted || history.length;
            var trust = Math.round(ds.trust || 0);
            var avgEquity = ds.avgEquity || 0;

            var insights = [];

            var counts = { voluntary: 0, threshold: 0, tax: 0, club: 0 };
            history.forEach(function(h) {
                var m = h.results && h.results.mechanism;
                if (m && counts.hasOwnProperty(m)) counts[m]++;
            });

            if (counts.voluntary >= 3 && funded < attempted * 0.5) {
                insights.push(window.mySimulation.t('insight_voluntary_heavy'));
            }
            if (counts.tax >= 4) {
                insights.push(window.mySimulation.t('insight_tax_heavy'));
            }
            if (counts.club >= 3) {
                insights.push(window.mySimulation.t('insight_club_heavy'));
            }
            if (avgEquity > 80 && funded >= attempted * 0.8) {
                insights.push(window.mySimulation.t('insight_balanced'));
            }
            if (trust < 25) {
                insights.push(window.mySimulation.t('insight_trust_broken'));
            }
            if (insights.length === 0) {
                insights.push(window.mySimulation.t('insight_default'));
            }

            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };
            var performance = t('rating_beginner');
            if (funded >= attempted * 0.6 && trust >= 40) performance = t('rating_good');
            if (funded >= attempted * 0.8 && trust >= 55 && avgEquity >= 60) performance = t('rating_excellent');

            return {
                overallScore: this._computeScore(ds),
                totalWelfare: totalWelfare,
                projectsFunded: funded,
                projectsAttempted: attempted,
                finalTrust: trust,
                avgEquity: avgEquity,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            summary = summary || {};
            var score = (summary.overallScore != null) ? summary.overallScore : null;
            var funded = (summary.projectsFunded != null) ? summary.projectsFunded : 0;
            var attempted = (summary.projectsAttempted != null) ? summary.projectsAttempted : 0;
            var trust = (summary.finalTrust != null) ? summary.finalTrust : 0;
            var equity = (summary.avgEquity != null) ? summary.avgEquity : 0;
            var welfare = (summary.totalWelfare != null) ? summary.totalWelfare : 0;
            var rating = summary.performance || '';
            var insights = Array.isArray(summary.insights) ? summary.insights : [];
            var items = insights.map(function(s) { return '<li>' + s + '</li>'; }).join('');
            var scoreBlock = (score != null)
